<section class="page-head"><div><p class="eyebrow">Analisis data</p><h2>Laporan Monitoring</h2><p>Ringkasan statistik seluruh parameter yang tersimpan.</p></div><div class="d-flex gap-2"><button class="btn btn-outline-primary" onclick="window.print()"><i class="bi bi-printer"></i> Cetak</button><button class="btn btn-primary" data-export-table="#reportTable"><i class="bi bi-filetype-csv"></i> Unduh CSV</button></div></section>
<div class="panel"><div class="table-responsive"><table class="table align-middle mb-0" id="reportTable"><thead><tr><th>Parameter</th><th>Satuan</th><th>Minimum</th><th>Maksimum</th><th>Rata-rata</th><th>Jumlah Data</th></tr></thead><tbody><?php foreach($summary as $row):?><tr><td><strong><?=e(str_replace('_',' ',$row['parameter']))?></strong></td><td><?=e($row['unit'])?></td><td><?=number_format((float)$row['minimum'],2,',','.')?></td><td><?=number_format((float)$row['maximum'],2,',','.')?></td><td><?=number_format((float)$row['average'],2,',','.')?></td><td><?=number_format((int)$row['total'],0,',','.')?></td></tr><?php endforeach?></tbody></table></div></div>

